anki_model.css:
.card {
  font-family: -apple-system, "Hiragino Sans", "Helvetica Neue", Arial, sans-serif;
  font-size: 17px;
  line-height: 1.75;
  text-align: left;
  max-width: 640px;
  margin: 0 auto;
  padding: 8px 4px 28px 4px;

  --bg: #e7e9ec;
  --fg: #1f2328;
  --sub: #6b7280;
  --word-bg: #eef2ff;
  --word-fg: #4338ca;
  --head-bg: #ccd1d7;
  --head-border: #b3b9c1;
  --meaning-bg: #ecdca0;
  --meaning-border: #c7a83a;
  --example-bg: #c7d3e2;
  --example-border: #5c85cf;
  --note-bg: #d6cde6;
  --note-border: #8567bd;
  --word-color: #000000;
  color: var(--fg);
  background: var(--bg);
}

.night_mode .card {
  --bg: #1a1c1f;
  --fg: #f0f1f3;
  --sub: #9aa1ab;
  --word-bg: #2b2f6b;
  --word-fg: #c7cdff;
  --head-bg: #212326;
  --head-border: #34373b;
  --meaning-bg: #332b10;
  --meaning-border: #8c7620;
  --example-bg: #182130;
  --example-border: #4d76b3;
  --note-bg: #201b28;
  --note-border: #7a5fc0;
  --word-color: var(--fg);
}

@media (prefers-color-scheme: dark) {
  .card {
    --bg: #1a1c1f;
    --fg: #f0f1f3;
    --sub: #9aa1ab;
    --word-bg: #2b2f6b;
    --word-fg: #c7cdff;
    --head-bg: #212326;
    --head-border: #34373b;
    --meaning-bg: #332b10;
    --meaning-border: #8c7620;
    --example-bg: #182130;
    --example-border: #4d76b3;
    --note-bg: #201b28;
    --note-border: #7a5fc0;
    --word-color: var(--fg);
  }
}

.head-block {
  background: var(--head-bg);
  border: 1px solid var(--head-border);
}
.word-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}
.word-main { font-size: 28px; font-weight: 700; color: var(--word-color); }
.word-reading { color: var(--sub); font-size: 15px; font-family: "SF Mono", Menlo, monospace; }
.word-pos {
  display: inline-block;
  background: var(--word-bg);
  color: var(--word-fg);
  font-size: 12.5px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
}

.block { border-radius: 12px; padding: 14px 16px; margin: 12px 0; }
.label { font-weight: 700; font-size: 12.5px; text-transform: uppercase; letter-spacing: .06em; margin-bottom: 6px; }

.meaning-block { background: var(--meaning-bg); border-left: 5px solid var(--meaning-border); }
.meaning-block .label { color: var(--meaning-border); }
.meaning-text { font-size: 19px; font-weight: 600; }

.example-block { background: var(--example-bg); border-left: 5px solid var(--example-border); }
.example-block .label { color: var(--example-border); }
.example-sentence { font-size: 16px; }
.example-ja { color: var(--sub); font-size: 14.5px; margin-top: 4px; }

.note-block { background: var(--note-bg); border-left: 5px solid var(--note-border); font-size: 15px; color: var(--word-color); }
.note-block .label { color: var(--note-border); }

.context-hint { color: var(--sub); font-size: 13px; margin-bottom: 6px; text-transform: uppercase; letter-spacing: .06em; font-weight: 700; }
.blank-sentence { font-size: 17px; background: var(--head-bg); border: 1px solid var(--head-border); border-radius: 12px; padding: 14px 16px; }

b { color: inherit; }
hr.sep { border: none; border-top: 1px solid var(--head-border); margin: 18px 0; }

.card {
  font-family: -apple-system, "Hiragino Sans", "Helvetica Neue", Arial, sans-serif;
  font-size: 17px;
  line-height: 1.75;
  text-align: left;
  max-width: 640px;
  margin: 0 auto;
  padding: 8px 4px 28px 4px;

  --bg: #e7e9ec;
  --fg: #000000;
  --sub: #6b7280;
  --pattern-bg: #eef2ff;
  --pattern-fg: #4338ca;
  --question-bg: #ccd1d7;
  --question-border: #b3b9c1;
  --choice-bg: #dcdfe3;
  --choice-border: #b3b9c1;
  --answer-bg: #ecdca0;
  --answer-border: #c7a83a;
  --why-bg: #c9dfc9;
  --why-border: #3a8f5c;
  --whynot-bg: #f0c9c9;
  --whynot-border: #c94a3f;
  --example-bg: #c7d3e2;
  --example-border: #5c85cf;
  --core-bg: #d6cde6;
  --core-border: #8567bd;
  color: var(--fg);
  background: var(--bg);
}

.night_mode .card {
  --bg: #1a1c1f;
  --fg: #f0f1f3;
  --sub: #9aa1ab;
  --pattern-bg: #2b2f6b;
  --pattern-fg: #c7cdff;
  --question-bg: #212326;
  --question-border: #34373b;
  --choice-bg: #24272a;
  --choice-border: #383c40;
  --answer-bg: #332b10;
  --answer-border: #8c7620;
  --why-bg: #16241b;
  --why-border: #3a7350;
  --whynot-bg: #271515;
  --whynot-border: #96453c;
  --example-bg: #182130;
  --example-border: #4d76b3;
  --core-bg: #201b28;
  --core-border: #7a5fc0;
}

@media (prefers-color-scheme: dark) {
  .card {
    --bg: #1a1c1f;
    --fg: #f0f1f3;
    --sub: #9aa1ab;
    --pattern-bg: #2b2f6b;
    --pattern-fg: #c7cdff;
    --question-bg: #212326;
    --question-border: #34373b;
    --choice-bg: #24272a;
    --choice-border: #383c40;
    --answer-bg: #332b10;
    --answer-border: #8c7620;
    --why-bg: #16241b;
    --why-border: #3a7350;
    --whynot-bg: #271515;
    --whynot-border: #96453c;
    --example-bg: #182130;
    --example-border: #4d76b3;
    --core-bg: #201b28;
    --core-border: #7a5fc0;
  }
}

.pattern-tag {
  display: inline-block;
  background: var(--pattern-bg);
  color: var(--pattern-fg);
  font-weight: 700;
  font-size: 14px;
  padding: 4px 12px;
  border-radius: 999px;
  margin-bottom: 12px;
  letter-spacing: 0.02em;
}

.block {
  border-radius: 12px;
  padding: 14px 16px;
  margin: 12px 0;
}

.question-block {
  background: var(--question-bg);
  border: 1px solid var(--question-border);
}
.question-label { font-size: 12px; color: var(--sub); font-weight: 700; margin-bottom: 6px; text-transform: uppercase; letter-spacing: .06em; }

.choices { margin-top: 10px; display: flex; flex-direction: column; gap: 6px; }
.choice {
  background: var(--choice-bg);
  border: 1px solid var(--choice-border);
  border-radius: 8px;
  padding: 7px 12px;
  font-family: "SF Mono", Menlo, monospace;
  font-size: 15.5px;
}

.answer-block {
  background: var(--answer-bg);
  border-left: 5px solid var(--answer-border);
}
.answer-block .label { font-weight: 700; font-size: 12.5px; color: var(--answer-border); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 4px;}
.answer-block .sentence { font-size: 18px; font-weight: 600; }

.example-block { background: var(--example-bg); border-left: 5px solid var(--example-border); }
.example-block .label { font-weight: 700; font-size: 12.5px; color: var(--example-border); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 6px; }
.example-item { margin: 0 0 10px 0; }
.example-item:last-child { margin-bottom: 0; }
.example-sentence { font-size: 16px; }
.example-ja { color: var(--sub); font-size: 14.5px; margin-top: 2px; }

.why-block { background: var(--why-bg); border-left: 5px solid var(--why-border); }
.why-block .label { font-weight: 700; font-size: 12.5px; color: var(--why-border); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 6px; }

.whynot-block { background: var(--whynot-bg); border-left: 5px solid var(--whynot-border); }
.whynot-block .label { font-weight: 700; font-size: 12.5px; color: var(--whynot-border); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 6px; }
.whynot-item { margin: 4px 0; }
.whynot-item .opt { font-family: "SF Mono", Menlo, monospace; font-weight: 700; }

.core-block { background: var(--core-bg); border-left: 5px solid var(--core-border); font-style: italic; font-size: 15.5px; }
.core-block .label { font-weight: 700; font-size: 12.5px; color: var(--core-border); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 6px; font-style: normal; }

b { color: inherit; }
hr.sep { border: none; border-top: 1px solid var(--question-border); margin: 18px 0; }

.masked b {
  color: transparent;
  background: var(--sub);
  border-radius: 4px;
  padding: 0 2px;
}

.ex-num { font-weight: 700; }

.blank-hint { color: var(--sub); font-size: 14px; margin-bottom: 10px; }
